package com.spectech.domain.util

/**
 * One city suggestion returned by [RegionCities.topCities]. Mirrors iOS
 * `CitySuggestion` (SpecTechIOS/Shared/Views/CitySearchField.swift).
 *
 * `subtitle` is the parent region name — shown beneath the city in the
 * picker to disambiguate names that repeat across regions (e.g. several
 * "Киров"s, "Богородск"s, "Берёзовский"s).
 */
data class CitySuggestion(val name: String, val subtitle: String? = null)

/**
 * Cities, towns, and major rural settlements (станицы) of the Russian
 * Federation organized by federal subject. Based on official data from ФИАС
 * (Federal Information Address System) and reliable open-source databases
 * (arbaev/russia-cities, Wikipedia).
 *
 * Map keys are the FULL official federal-subject names, exactly as listed in
 * [RussianRegions.all] ("Краснодарский край", "Республика Адыгея", …) — the
 * region pickers commit those full strings, and [topCities] looks entries up
 * by exact match. `RegionCitiesTest` guards the two lists against drifting
 * apart.
 *
 * Besides cities, the Cossack-belt subjects (Краснодарский край, Ростовская
 * область, Ставропольский край, and the North Caucasus republics) include
 * their major станицы so orders can target rural job sites there.
 *
 * Used as the suggestion source for the city pickers (Create Order single-
 * select; Marketplace/Orders filter multi-select) in place of the iOS MapKit
 * `MKLocalSearchCompleter`. A Google Places integration replaces this once
 * the API key is available — the picker UI stays unchanged.
 *
 * Federal cities (Москва, Санкт-Петербург, Севастополь) map to themselves.
 *
 * Lives in `core/domain/util` because `:features:create-order`,
 * `:features:marketplace`, and `:features:orders` all need it.
 */
object RegionCities {

    /** Returns deduplicated, region-tagged suggestions for the given regions. */
    fun topCities(regions: Set<String>): List<CitySuggestion> {
        if (regions.isEmpty()) return emptyList()
        val result = mutableListOf<CitySuggestion>()
        val seen = mutableSetOf<String>()
        for (region in regions.sorted()) {
            val cities = cityMap[region] ?: continue
            for (city in cities) {
                val key = city.lowercase()
                if (key in seen) continue
                seen += key
                result += CitySuggestion(name = city, subtitle = region)
            }
        }
        return result
    }

    /** Convenience for single-region callers (matches the iOS `region:` overload). */
    fun topCities(region: String): List<CitySuggestion> =
        topCities(setOf(region))

    /** All federal subjects that have suggestion data — used by tests. */
    val knownRegions: Set<String> get() = cityMap.keys

